from pathlib import Path
import base64, gzip, hashlib, subprocess
payload = ''''''
# The transfer is rejected before touching code if its checksum differs.
patch = gzip.decompress(base64.b64decode(payload))
assert hashlib.sha256(patch).hexdigest() == 'e26c1969a9fa28f7c5f97f39efe880bd9aabbf40f97b926dbb80b2bd5dce784e'
subprocess.run(['git', 'apply', '--check', '-'], input=patch, check=True)
subprocess.run(['git', 'apply', '-'], input=patch, check=True)
